<?php $current=$access['plan'];$subscription=$access['subscription'];$usage=$access['usage'];$limits=$access['limits'];$featureLabels=['advanced_analytics'=>'Advanced analytics','catalog_import'=>'CSV / Excel import','bulk_image_import'=>'Bulk image matching','remove_platform_branding'=>'Remove platform branding','premium_customization'=>'Expanded customization'];$limitLabel=static fn(mixed$value)=>((int)$value<0?'Unlimited':(string)(int)$value); ?>
<section class="subscription-page"><div class="page-head"><div><p class="eyebrow">Subscription</p><h1>Plan and usage</h1><p class="muted">Limits and paid features are enforced on the server. Existing data is preserved if a plan changes.</p></div><span class="badge <?= strtolower((string)($subscription['status']??'ACTIVE')) ?>"><?= e($subscription['status']??'FREE') ?></span></div>
<?php if($access['is_fallback']):?><div class="notice warning"><strong>Free limits are currently active.</strong> The previous paid entitlement has expired or is outside its valid period. Existing products remain saved, but new actions follow Free-plan limits.</div><?php endif ?>
<div class="subscription-summary"><section class="panel current-plan"><div><span class="eyebrow">Current entitlement</span><h2><?= e($current['name']) ?></h2><p><?= e($current['description']??'') ?></p></div><strong><?= (float)$current['monthly_price']>0?e($current['currency_code']).' '.e($current['monthly_price']).' / month':'Free' ?></strong><dl><div><dt>Subscription state</dt><dd><?= e($subscription['status']??'ACTIVE') ?></dd></div><?php if($subscription&&$subscription['trial_ends_at']):?><div><dt>Trial ends</dt><dd><?= e(gmdate('M j, Y',strtotime($subscription['trial_ends_at']))) ?></dd></div><?php endif ?><?php if($subscription&&$subscription['current_period_ends_at']):?><div><dt>Current period ends</dt><dd><?= e(gmdate('M j, Y',strtotime($subscription['current_period_ends_at']))) ?></dd></div><?php endif ?><?php if($subscription&&$subscription['grace_ends_at']):?><div><dt>Grace ends</dt><dd><?= e(gmdate('M j, Y',strtotime($subscription['grace_ends_at']))) ?></dd></div><?php endif ?><?php if($subscription&&$subscription['pending_plan_name']):?><div><dt>Scheduled plan</dt><dd><?= e($subscription['pending_plan_name']) ?><?= $subscription['scheduled_change_at']?' · '.e(gmdate('M j, Y',strtotime($subscription['scheduled_change_at']))):'' ?></dd></div><?php endif ?></dl></section>
<section class="panel usage-card"><span class="eyebrow">Current usage</span><h2>Store resources</h2><?php foreach(['products'=>'Products','categories'=>'Categories','staff'=>'Staff members']as$key=>$label):?><?php $used=(int)($usage[$key]??0);$limit=(int)($limits[$key]??-1);$percent=$limit<0?0:min(100,(int)round(($used/max(1,$limit))*100));?><div class="usage-row"><div><strong><?= e($label) ?></strong><span><?= e($used) ?> / <?= e($limitLabel($limit)) ?></span></div><div class="usage-meter <?= $limit>=0&&$used>=$limit?'full':'' ?>"><i style="width:<?= e($limit<0?8:$percent) ?>%"></i></div></div><?php endforeach ?></section></div>
<div class="plan-grid"><?php foreach($plans as$plan):?><?php $isCurrent=(int)$plan['id']===(int)$current['id'];$renewalDue=$isCurrent&&$subscription&&((in_array($subscription['status'],['PAST_DUE','GRACE','EXPIRED'],true))||($subscription['status']==='ACTIVE'&&$subscription['current_period_ends_at']&&strtotime($subscription['current_period_ends_at'])<=time())||($subscription['status']==='TRIAL'&&$subscription['trial_ends_at']&&strtotime($subscription['trial_ends_at'])<=time()));?><article class="plan-card <?= $isCurrent?'current':'' ?>"><header><div><span><?= e($plan['name']) ?></span><p><?= e($plan['description']??'') ?></p></div><strong><?= (float)$plan['monthly_price']>0?e($plan['currency_code']).' '.e($plan['monthly_price']):'Free' ?><small><?= (float)$plan['monthly_price']>0?'/ month':'' ?></small></strong></header><ul><li><?= e($limitLabel($plan['limits']['products']??-1)) ?> products</li><li><?= e($limitLabel($plan['limits']['categories']??-1)) ?> categories</li><li><?= e($limitLabel($plan['limits']['stores']??1)) ?> store<?= (int)($plan['limits']['stores']??1)===1?'':'s' ?></li><?php foreach($featureLabels as$key=>$label):?><li class="<?= !($plan['features'][$key]??false)?'muted-feature':'' ?>"><?= ($plan['features'][$key]??false)?'✓':'—' ?> <?= e($label) ?></li><?php endforeach ?></ul><?php if($isCurrent&&!$renewalDue):?><span class="button secondary plan-current">Current plan</span><?php else:?><form method="post" action="/merchant/subscription/change" data-confirm="Request <?= e($renewalDue?'renewal':'the '.$plan['name'].' plan') ?>?" data-confirm-message="Paid access is never granted until payment is confirmed. Free downgrades may apply at the current period end."><?= csrf_field() ?><input type="hidden" name="plan_code" value="<?= e($plan['code']) ?>"><button class="button <?= $renewalDue||(int)$plan['sort_order']>(int)$current['sort_order']?'primary':'secondary' ?>" type="submit"><?= $renewalDue?'Request renewal':((int)$plan['sort_order']>(int)$current['sort_order']?'Request upgrade':'Choose plan') ?></button></form><?php endif ?></article><?php endforeach ?></div>
<section class="panel change-history"><div class="panel-title"><h2>Plan changes</h2><span>Latest requests</span></div><?php if(!$requests):?><div class="empty-inline">No plan changes have been requested.</div><?php else:?><div class="change-list"><?php foreach($requests as$change):?><article><div><strong><?= e($change['from_plan_name']) ?> → <?= e($change['to_plan_name']) ?></strong><small><?= e(ucfirst(strtolower($change['change_type']))) ?> · <?= e(gmdate('M j, Y H:i',strtotime($change['created_at']))) ?></small></div><span class="badge <?= strtolower($change['status']) ?>"><?= e($change['status']) ?></span><?php if(in_array($change['status'],['PENDING','SCHEDULED'],true)):?><form method="post" action="/merchant/subscription/changes/<?= e($change['id']) ?>/cancel" data-confirm="Cancel this plan change?" data-confirm-message="The current plan will remain unchanged."><?= csrf_field() ?><button class="button compact danger-ghost" type="submit">Cancel</button></form><?php endif ?></article><?php endforeach ?></div><?php endif ?></section>
<p class="billing-note">Manual billing is configured. A paid request remains pending until a trusted server-side activation confirms payment. No card data is collected or stored by this application.</p></section>
